SELECT events_agg.unique_users AS unique_users, events_agg.previous_unique_users AS previous_unique_users, events_agg.total_filtered_pageview_count AS total_filtered_pageview_count, events_agg.previous_total_filtered_pageview_count AS previous_total_filtered_pageview_count, sessions_agg.unique_sessions AS unique_sessions, sessions_agg.previous_unique_sessions AS previous_unique_sessions, sessions_agg.avg_duration_s AS avg_duration_s, sessions_agg.previous_avg_duration_s AS previous_avg_duration_s, sessions_agg.bounce_rate AS bounce_rate, sessions_agg.previous_bounce_rate AS previous_bounce_rate FROM (SELECT uniqIf(if(not(empty(events__override.distinct_id)), events__override.person_id, events.person_id), and(greaterOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))))) AS unique_users, NULL AS previous_unique_users, countIf(and(greaterOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))))) AS total_filtered_pageview_count, NULL AS previous_total_filtered_pageview_count FROM events_json AS events LEFT OUTER JOIN (SELECT argMax(person_distinct_id_overrides.person_id, person_distinct_id_overrides.version) AS person_id, person_distinct_id_overrides.distinct_id AS distinct_id FROM person_distinct_id_overrides WHERE equals(person_distinct_id_overrides.team_id, TEAM_ID) GROUP BY person_distinct_id_overrides.distinct_id HAVING equals(argMax(person_distinct_id_overrides.is_deleted, person_distinct_id_overrides.version), 0) SETTINGS optimize_aggregation_in_order=1) AS events__override ON equals(events.distinct_id, events__override.distinct_id) WHERE and(equals(events.team_id, TEAM_ID), and(isNotNull(toUInt128(toUUIDOrNull(events.properties.`$session_id`))), or(equals(events.event, '$pageview'), equals(events.event, '$screen')), or(and(greaterOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')))), 0), 1))) AS events_agg CROSS JOIN (SELECT uniqIf(sessions.session_id, and(greaterOrEquals(sessions.`$start_timestamp`, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(sessions.`$start_timestamp`, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))))) AS unique_sessions, NULL AS previous_unique_sessions, avgIf(sessions.`$session_duration`, and(greaterOrEquals(sessions.`$start_timestamp`, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(sessions.`$start_timestamp`, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))))) AS avg_duration_s, NULL AS previous_avg_duration_s, avgIf(sessions.`$is_bounce`, and(greaterOrEquals(sessions.`$start_timestamp`, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(sessions.`$start_timestamp`, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))))) AS bounce_rate, NULL AS previous_bounce_rate FROM (SELECT toString(reinterpretAsUUID(bitOr(bitShiftLeft(raw_sessions_v3.session_id_v7, 64), bitShiftRight(raw_sessions_v3.session_id_v7, 64)))) AS session_id, min(toTimeZone(raw_sessions_v3.min_timestamp, 'UTC')) AS `$start_timestamp`, dateDiff('second', min(toTimeZone(raw_sessions_v3.min_timestamp, 'UTC')), max(toTimeZone(raw_sessions_v3.max_timestamp, 'UTC'))) AS `$session_duration`, if(equals(uniqUpToMerge(1)(raw_sessions_v3.page_screen_uniq_up_to), 0), NULL, not(or(greaterOrEquals(uniqUpToMerge(1)(raw_sessions_v3.page_screen_uniq_up_to), 2), max(raw_sessions_v3.has_autocapture), greaterOrEquals(dateDiff('second', min(toTimeZone(raw_sessions_v3.min_timestamp, 'UTC')), max(toTimeZone(raw_sessions_v3.max_timestamp, 'UTC'))), 10)))) AS `$is_bounce`, uniqMerge(raw_sessions_v3.pageview_uniq) AS `$pageview_count`, uniqMerge(raw_sessions_v3.screen_uniq) AS `$screen_count`, raw_sessions_v3.session_id_v7 AS session_id_v7 FROM raw_sessions_v3 WHERE and(equals(raw_sessions_v3.team_id, TEAM_ID), greaterOrEquals(raw_sessions_v3.session_timestamp, minus(assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC')), toIntervalDay(3))), lessOrEquals(raw_sessions_v3.session_timestamp, plus(assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')), toIntervalDay(3)))) GROUP BY raw_sessions_v3.session_id_v7) AS sessions WHERE and(or(and(greaterOrEquals(sessions.`$start_timestamp`, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(sessions.`$start_timestamp`, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')))), 0), or(greater(sessions.`$pageview_count`, 0), greater(sessions.`$screen_count`, 0)), 1)) AS sessions_agg LIMIT 50000
